def md_to_html(line):
    """Convert a single markdown line to HTML."""
    stripped = line.strip()
    if not stripped:
        return '<br>'
    if stripped.startswith('## '):
        return f'<h2>{stripped[3:]}</h2>'
    elif stripped.startswith('### '):
        return f'<h3>{stripped[4:]}</h3>'
    elif stripped.startswith('#### '):
        return f'<h4>{stripped[5:]}</h4>'
    elif stripped.startswith('---'):
        return '<hr>'
    elif stripped.startswith('> '):
        return f'<blockquote>{stripped[2:]}</blockquote>'
    elif stripped.startswith('- ') or stripped.startswith('* '):
        return f'<li>{stripped[2:]}</li>'
    elif re.match(r'^\d+\.', stripped):
        return f'<li>{stripped}</li>'
    elif stripped.startswith('**') and stripped.endswith('**'):
        return f'<p><strong>{stripped[2:-2]}</strong></p>'
    else:
        # Bold/italic inline
        text = stripped
        text = re.sub(r'\*\*(.+?)\*\*', r'<strong>\1</strong>', text)
        text = re.sub(r'\*(.+?)\*', r'<em>\1</em>', text)
        return f'<p>{text}</p>'


def process_markdown_section(lines, start_marker=None, section_class="chapter"):
    """Process lines into HTML, starting from a marker or from line 0."""
    result = []
    started = False if start_marker else True
    for line in lines:
        stripped = line.strip()
        if start_marker and not started:
            if start_marker in stripped:
                started = True
                result.append(f'<div class="{section_class}">')
                result.append(f'<h2>{stripped}</h2>')
            continue
        if started:
            if stripped.startswith('## Chapter') or stripped.startswith('## Appendix'):
                # Close current section, open new one
                result.append('</div>')
                result.append(f'<div class="{section_class}">')
                result.append(f'<h2>{stripped[3:].strip()}</h2>')
            elif stripped.startswith('## '):
                result.append(f'<h2>{stripped[3:]}</h2>')
            elif stripped.startswith('### '):
                result.append(f'<h3>{stripped[4:]}</h3>')
            elif stripped.startswith('#### '):
                result.append(f'<h4>{stripped[5:]}</h4>')
            elif stripped.startswith('---'):
                result.append('<hr>')
            elif stripped == '':
                result.append('<br>')
            elif stripped.startswith('> '):
                result.append(f'<blockquote>{stripped[2:]}</blockquote>')
            elif stripped.startswith('- ') or stripped.startswith('* '):
                result.append(f'<li>{stripped[2:]}</li>')
            elif re.match(r'^\d+[\.\)]', stripped):
                # Remove leading number for cleaner list display
                text = re.sub(r'^\d+[\.\)]\s*', '', stripped)
                result.append(f'<li>{text}</li>')
            elif stripped.startswith('|'):
                # Table row — skip for simplicity
                result.append(f'<p>{stripped}</p>')
            else:
                # Regular paragraph with inline formatting
                text = stripped
                text = re.sub(r'\*\*(.+?)\*\*', r'<strong>\1</strong>', text)
                text = re.sub(r'\*(.+?)\*', r'<em>\1</em>', text)
                # Handle code spans
                text = re.sub(r'`(.+?)`', r'<code>\1</code>', text)
                result.append(f'<p>{text}</p>')

    if result and not result[-1].startswith('</div>'):
        result.append('</div>')
    return result


def build_toc(md_lines, include_appendix=True):
    """Build a clean TOC from the markdown."""
    toc = ['<div class="toc-page">', '<h2>Table of Contents</h2>', '<ul>']
    toc.append('<li><strong>Introduction</strong> by Robert Mills</li>')
    toc.append('<li><strong>Preface:</strong> The AI Advantage</li>')
    for i in range(1, 13):
        toc.append(f'<li>Chapter {i}</li>')
    if include_appendix:
        toc.append('<li><strong>Appendix:</strong> The Small Business Growth Engine</li>')
    toc.append('</ul>', '</div>')
    return toc


