            continue
        if stripped.startswith('A CASE STUDY') or stripped.startswith('The Small Business\nGrowth Engine'):
            continue
        if stripped.startswith('How One Man Built') and '12-Person' in stripped:
            continue
        if stripped.startswith('This book tells the story'):
